/**
 * Certificates and requests made by OpenSSL 3.5.5 with make-fixtures.sh in this folder, and what OpenSSL printed for each of
 * them. The values are literals: the unit tests never run OpenSSL. Each certificate is the Base64 of its DER; the PEM
 * armour is put around it by the test. No private key is here (the keys stayed in the scratch folder and were deleted).
 * Carriage returns that Windows OpenSSL writes were removed from every printed line.
 */

export interface OpenSslCertificate {
  /** The Base64 of the DER bytes. */
  derB64: string;
  /** The fingerprint as openssl x509 -fingerprint -sha256 prints it (after the equals sign). */
  sha256: string;
  sha1: string;
  md5: string;
  /** The text after serial= . */
  serial: string;
  /** The text after subject= with -nameopt RFC2253,-esc_msb. */
  subjectRfc2253: string;
  issuerRfc2253: string;
  /** The text after subject= with -nameopt oneline,-esc_msb,-space_eq. */
  subjectOneline: string;
  issuerOneline: string;
  /** openssl x509 -dates, the two lines after notBefore= and notAfter= . */
  notBefore: string;
  notAfter: string;
  /** openssl x509 -pubkey piped to openssl pkey -pubin -outform DER piped to openssl dgst -sha256, lower case hex. */
  spkiSha256Hex: string;
  /** openssl x509 -noout -text, one array entry per line. */
  text: string[];
}

/** A certificate of the chain fixtures: what OpenSSL printed, and its two key identifiers as colon hex. */
export interface ChainCertificate extends OpenSslCertificate {
  ski: string;
  aki: string;
}

export interface OpenSslRequest {
  derB64: string;
  subjectRfc2253: string;
  /** openssl req -outform DER piped to openssl dgst -sha256, lower case hex. */
  requestSha256Hex: string;
  /** openssl req -noout -text, one array entry per line. */
  text: string[];
}

